import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [process(item) for item in obj if item is not None]
        elif isinstance(obj, str):
            return re.sub(r'\b[\w\.-]+@[\w\.-]+\.\w+\b', REPLACE_NONE, obj)
        else:
            return obj
    processed = process(data)
    def extract_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from extract_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_values(item)
        else:
            yield obj
    values = list(extract_values(processed))
    counts = Counter(values)
    return {"data": processed, "value_counts": counts}
